__NUXT_JSONP__("/think-tanks/publicaciones/information_integrity_and_ai_regulation_a_path_forward", (function(a,b,c,d,e,f,g,h,i,j,k,l,m,n,o,p,q,r,s,t){return {data:[{post:{slug:h,title:e,date:i,img:j,"img-alt":e,autor:k,category:l,extracto:f,file:m,toc:[],body:{type:n,children:[{type:b,tag:c,props:{},children:[{type:a,value:o}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:f}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:p}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:q}]}]},dir:r,path:s,extension:t,createdAt:g,updatedAt:g},publicaciones:[{slug:h,title:e,date:i,img:j,"img-alt":e,autor:k,category:l,extracto:f,file:m,toc:[],body:{type:n,children:[{type:b,tag:c,props:{},children:[{type:a,value:o}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:f}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:p}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:q}]}]},dir:r,path:s,extension:t,createdAt:g,updatedAt:g}]}],fetch:{},mutations:[]}}("text","element","p","\n","Information Integrity and AI Regulation: A Path Forward","This policy brief examines global trends in disinformation governance, analysing the rising number of regulatory initiatives, the geopolitical landscape, and the implications of AI-driven manipulation. It underscores the need for balanced, human rights-based policies that combine accountability with citizen empowerment, particularly in light of commitments made through frameworks like the UN Global Digital Compact and the G20 AI Principles.","2025-11-25T01:24:03.296Z","information_integrity_and_ai_regulation_a_path_forward","2025-11-18T16:35:41.750Z","https:\u002F\u002Fucarecdn.com\u002F14033485-162b-4136-b5ef-b2261101f3c0\u002F","Carme Colomina, Javier Gonzalez y José García","think-tanks","https:\u002F\u002Fucarecdn.com\u002F41cd5685-ed6e-4998-a6c7-e47e370d8217\u002F","root","Disinformation, particularly when amplified by artificial intelligence (AI), poses a growing threat to democracies worldwide by undermining access to reliable information – a right recognised under international law. As AI technologies rapidly evolve, they facilitate the creation and dissemination of false content at scale, raising urgent concerns about information integrity and democratic resilience. In response, a diverse array of national and regional regulatory approaches has emerged, ranging from content oversight to media literacy initiatives. However, these responses remain fragmented and uneven across countries.","The brief proposes key recommendations for the G20, including establishing a High-Level Task Force on AI and Information Integrity, encouraging ethical AI guidelines, and fostering global cooperation. It advocates for regulatory models that balance freedom of expression with protections against hate speech, based on international human rights standards such as the UN Rabat Plan of Action. It also calls on internet intermediaries to ensure algorithmic transparency and human rights accountability.","Finally, it emphasises the role of civil society, academia, and non-governmental organisations in promoting digital literacy – especially among marginalised groups – to ensure that societies can navigate the evolving digital landscape with resilience and informed agency.","\u002Fpublicaciones","\u002Fpublicaciones\u002Finformation_integrity_and_ai_regulation_a_path_forward",".md")));